// 왜 tx(ko, en) 호출 1500여 곳을 직접 고치지 않는가 — gettext 방식
// (gettext: 프로그램이 번역할 문장을 코드에 그대로 적어 두고, 그 원문 자체를 키로 써서
// 번역을 찾는 오래된 방식. 우리 코드가 부르는 방식과 이미 같다: tx(ko, en)의 ko 가
// 곧 원문이자 키다)을 그대로 쓴다. 호출부는 하나도 안 건드리고, 이 표 하나만 채우면
// 새 언어가 화면에 나타난다. 대신 한국어 원문이 바뀌면 이 표의 그 줄도 같이 고쳐야
// 한다 — 원문과 키가 같은 문자열이기 때문이다. src/i18n/index.ts 의 pickLanguage 가
// 이 표를 먼저 찾고, 없으면 영어로 떨어진다(기존 규칙 그대로).
export type Translation = { ja?: string; zhHans?: string; zhHant?: string };

