  '진행 상태는 이 기기에만 저장돼요. 다른 기기에서는 아직 안 보여요.': { ja: '進行状況はこの端末にだけ保存されます。ほかの端末ではまだ表示されません。', zhHans: '进度只保存在本设备上，其他设备暂时看不到。', zhHant: '進度只儲存在本裝置上，其他裝置暫時看不到。' },
