  '동선 지도는 준비 중이에요. 장소의 좌표가 들어오면 여기에 선으로 그려 드려요.': { ja: '動線の地図は準備中です。場所の座標が入ると、ここに線で描きます。', zhHans: '路线地图还在准备中。地点坐标到位后会在这里画出连线。', zhHant: '路線地圖還在準備中。地點座標到位後會在這裡畫出連線。' },
  '코스를 고르면 내용이 여기에 보여요.': { ja: 'コースを選ぶと内容がここに表示されます。', zhHans: '选择路线后，内容会显示在这里。', zhHant: '選擇路線後，內容會顯示在這裡。' },
