  '이 코스로 일정 만들기': { ja: 'このコースで日程を作る', zhHans: '用这条路线生成行程', zhHant: '用這條路線生成行程' },
  '이 기능은 아직 준비 중이에요. 준비되면 바로 쓸 수 있어요.': { ja: 'この機能はまだ準備中です。準備ができ次第すぐに使えます。', zhHans: '此功能还在准备中，准备好后即可使用。', zhHant: '此功能還在準備中，準備好後即可使用。' },
  '확인되지 않은 곳이 있어요': { ja: '未確認の場所があります', zhHans: '有尚未确认的地点', zhHant: '有尚未確認的地點' },
  '갈 수 없다는 뜻은 아니에요. 아직 아무도 확인하지 않았다는 뜻이에요. 가는 길의 경사는 반영했습니다.': { ja: '行けないという意味ではありません。まだ誰も確認していないという意味です。道の傾斜は反映しています。', zhHans: '这不代表去不了，只是还没有人确认过。前往路线的坡度已纳入考虑。', zhHant: '這不代表去不了，只是還沒有人確認過。前往路線的坡度已納入考量。' },
  '이 여행에는 일정이 없어요.': { ja: 'この旅行には日程がありません。', zhHans: '这次旅行还没有行程。', zhHant: '這次旅行還沒有行程。' },
