  '일정 물어보기': { ja: '日程を相談する', zhHans: '咨询行程', zhHant: '諮詢行程' },
  '여행 계획 시작해 보세요': { ja: '旅行の計画を始めてみましょう', zhHans: '开始规划旅行吧', zhHant: '開始規劃旅行吧' },
  '앱 지도를 그리려면 빌드할 때 카카오 지도 키가 함께 들어가야 하는데, 이 빌드에는 빈 값이 들어갔습니다. 방문 순서와 장소 목록은 아래에서 그대로 볼 수 있어요.': { ja: 'アプリの地図を表示するにはビルド時に Kakao マップのキーが必要ですが、このビルドには空の値が入っています。訪問順と場所の一覧は下にそのまま表示されます。', zhHans: '显示应用内地图需要在构建时带入 Kakao 地图密钥，但此构建中该值为空。访问顺序和地点列表仍可在下方查看。', zhHant: '顯示應用內地圖需要在建置時帶入 Kakao 地圖金鑰，但此建置中該值為空。造訪順序和地點清單仍可在下方查看。' },
  '카카오 지도 파일을 받지 못했습니다. 네트워크가 막혔거나, 이 앱이 카카오 개발자 콘솔에 등록되지 않았을 수 있습니다.': { ja: 'Kakao マップのファイルを取得できませんでした。ネットワークが遮断されているか、このアプリが Kakao デベロッパーコンソールに登録されていない可能性があります。', zhHans: '未能获取 Kakao 地图文件。可能是网络被阻断，或此应用未在 Kakao 开发者控制台注册。', zhHant: '未能取得 Kakao 地圖檔案。可能是網路被阻斷，或此應用未在 Kakao 開發者控制台註冊。' },
  '옅은 선은 어림한 길이라 실제로 가는 길과 다를 수 있어요.': { ja: '薄い線は推定のルートなので、実際の道と異なる場合があります。', zhHans: '浅色线是估算路线，可能与实际路线不同。', zhHant: '淺色線是估算路線，可能與實際路線不同。' },
  '메뉴는 아직 영어로 나와요. 장소 이름과 안내는 고른 언어로 나와요.': { ja: 'メニューはまだ英語で表示されます。場所の名前と案内は選んだ言語で表示されます。', zhHans: '菜单目前仍显示英文。地点名称和指引会按您选择的语言显示。', zhHant: '選單目前仍顯示英文。地點名稱和指引會按您選擇的語言顯示。' },
  '프로필 편집': { ja: 'プロフィールを編集', zhHans: '编辑主页资料', zhHant: '編輯個人資料' },
  '다른 여행자의 기록 중 눌러 담아 둔 것이에요.': { ja: 'ほかの旅行者の記録の中から保存したものです。', zhHans: '这些是您从其他旅行者的记录中收藏的内容。', zhHant: '這些是您從其他旅行者的記錄中收藏的內容。' },
  '나를 팔로우하는 사람들이에요.': { ja: 'あなたをフォローしている人たちです。', zhHans: '这些是关注您的人。', zhHant: '這些是追蹤您的人。' },
  '내가 팔로우하는 사람들이에요.': { ja: 'あなたがフォローしている人たちです。', zhHans: '这些是您关注的人。', zhHant: '這些是您追蹤的人。' },
