  '내가 올린 사진만 커버로 쓸 수 있어요.': { ja: '自分がアップした写真だけカバーに使えます。', zhHans: '只能把自己上传的照片设为封面。', zhHant: '只能把自己上傳的照片設為封面。' },
  '커버 사진을 바꾸지 못했어요.': { ja: 'カバー写真を変更できませんでした。', zhHans: '未能更换封面照片。', zhHant: '未能更換封面照片。' },
  '현재 커버 사진': { ja: '現在のカバー写真', zhHans: '当前封面照片', zhHant: '目前封面照片' },
  '기본 커버 사진': { ja: '既定のカバー写真', zhHans: '默认封面照片', zhHant: '預設封面照片' },
  '커버 사진': { ja: 'カバー写真', zhHans: '封面照片', zhHant: '封面照片' },
  '마이페이지 맨 위에 깔려요': { ja: 'マイページの一番上に表示されます', zhHans: '会显示在我的主页顶部', zhHant: '會顯示在我的主頁頂部' },
  '아직 기본 사진이에요': { ja: 'まだ既定の写真です', zhHans: '目前仍是默认照片', zhHant: '目前仍是預設照片' },
  '바꾸기': { ja: '変更', zhHans: '更换', zhHant: '更換' },
  '저장한 기록을 불러오지 못했어요': { ja: '保存した記録を読み込めませんでした', zhHans: '无法加载收藏的记录', zhHant: '無法載入收藏的記錄' },
  '아직 저장한 기록이 없어요': { ja: 'まだ保存した記録がありません', zhHans: '还没有收藏的记录', zhHant: '還沒有收藏的記錄' },
  '피드에서 마음에 드는 기록을 눌러 저장해 보세요.': { ja: 'フィードで気に入った記録をタップして保存してみましょう。', zhHans: '在动态里点击喜欢的记录来收藏吧。', zhHant: '在動態裡點擊喜歡的記錄來收藏吧。' },
