  // 사진 크게 보기 — 커버(S15P21E201-1810) · 피드(S15P21E201-1811).
  '배경 사진 크게 보기': { ja: 'カバー写真を大きく見る', zhHans: '查看大图封面照片', zhHant: '檢視大圖封面照片' },
  '사진 닫기': { ja: '写真を閉じる', zhHans: '关闭照片', zhHant: '關閉照片' },
  '사진 크게 보기': { ja: '写真を大きく見る', zhHans: '查看大图', zhHant: '檢視大圖' },
  '여행 조건 미리 알려주기': { ja: '旅行の条件を先に伝える', zhHans: '提前告知旅行条件', zhHant: '提前告知旅行條件' },
  '일정을 만들기 전에 여행 조건을 알려주실래요? 건너뛰면 다음 「일정 물어보기」 때 다시 물어요.': { ja: '日程を作る前に旅行の条件を教えていただけますか? スキップすると次の「日程を相談する」のときにまたお尋ねします。', zhHans: '生成行程前可以先告诉我们旅行条件吗? 跳过的话，下次「咨询行程」时会再询问。', zhHant: '生成行程前可以先告訴我們旅行條件嗎? 跳過的話，下次「諮詢行程」時會再詢問。' },
  // 🔴 알레르기를 빼고 식단만 남긴 판 (S15P21E201-1497). 위의 옛 문구는 지우지 않는다 —
  //    ALLERGEN_TAG 가 쌓여 질문을 다시 열면 그대로 쓴다.
  '식단은 안전에 걸리는 것이라, 모르면 안전하다고 치지 않아요. 한 번만 알려주시면 다음부터 안 물어봐요.': { ja: '食事制限は安全に関わるため、分からない場合は安全とみなしません。一度教えていただければ次からはお尋ねしません。', zhHans: '饮食限制关系到安全，未知时我们不会当作安全。只要告诉我们一次，之后就不会再问。', zhHant: '飲食限制關係到安全，未知時我們不會當作安全。只要告訴我們一次，之後就不會再問。' },
  '알레르기와 식단은 안전에 걸리는 것이라, 모르면 안전하다고 치지 않아요. 한 번만 알려주시면 다음부터 안 물어봐요.': { ja: 'アレルギーと食事制限は安全に関わるため、分からない場合は安全とみなしません。一度教えていただければ次からはお尋ねしません。', zhHans: '过敏和饮食限制关系到安全，未知时我们不会当作安全。只要告诉我们一次，之后就不会再问。', zhHant: '過敏和飲食限制關係到安全，未知時我們不會當作安全。只要告訴我們一次，之後就不會再問。' },
  '이동 환경': { ja: '移動環境', zhHans: '出行条件', zhHant: '出行條件' },
  // 추천 실패 — 어느 조건이 막았나 (S15P21E201-1514, src/plan/blockedByMessage.ts).
  // 🔴 「확인된 곳이 없어」와 「지키는 곳을 찾지 못해」는 다른 말이다 — 앞쪽은 자료가 없는 것이고
  //    뒤쪽은 확인했는데 안 맞은 것이다. 번역에서도 둘을 합치지 않는다.
  '안 맞는다는 뜻이 아니라, 아직 확인한 자료가 없어요.': { ja: '合わないという意味ではなく、まだ確認できる資料がないだけです。', zhHans: '这并不代表不符合，只是还没有可供确认的资料。', zhHant: '這並不代表不符合，只是還沒有可供確認的資料。' },
  '걸린 조건:': { ja: '該当した条件：', zhHans: '受限条件：', zhHant: '受限條件：' },
  '이동 조건': { ja: '移動条件', zhHans: '出行条件', zhHant: '出行條件' },
  '알레르기 조건에 맞는지 확인된 곳이 없어 일정을 만들지 못했어요.': { ja: 'アレルギー条件に合うと確認できた場所がなく、日程を作れませんでした。', zhHans: '没有能确认符合过敏条件的地点，因此无法生成行程。', zhHant: '沒有能確認符合過敏條件的地點，因此無法產生行程。' },
  '알레르기 조건을 지키는 곳을 찾지 못해 일정을 만들지 못했어요.': { ja: 'アレルギー条件を守れる場所が見つからず、日程を作れませんでした。', zhHans: '找不到符合过敏条件的地点，因此无法生成行程。', zhHant: '找不到符合過敏條件的地點，因此無法產生行程。' },
  '식단 조건에 맞는지 확인된 곳이 없어 일정을 만들지 못했어요.': { ja: '食事制限に合うと確認できた場所がなく、日程を作れませんでした。', zhHans: '没有能确认符合饮食条件的地点，因此无法生成行程。', zhHant: '沒有能確認符合飲食條件的地點，因此無法產生行程。' },
  '식단 조건을 지키는 곳을 찾지 못해 일정을 만들지 못했어요.': { ja: '食事制限を守れる場所が見つからず、日程を作れませんでした。', zhHans: '找不到符合饮食条件的地点，因此无法生成行程。', zhHant: '找不到符合飲食條件的地點，因此無法產生行程。' },
  '이동 조건에 맞는지 확인된 곳이 없어 일정을 만들지 못했어요.': { ja: '移動条件に合うと確認できた場所がなく、日程を作れませんでした。', zhHans: '没有能确认符合出行条件的地点，因此无法生成行程。', zhHant: '沒有能確認符合出行條件的地點，因此無法產生行程。' },
  '이동 조건을 지키는 곳을 찾지 못해 일정을 만들지 못했어요.': { ja: '移動条件を守れる場所が見つからず、日程を作れませんでした。', zhHans: '找不到符合出行条件的地点，因此无法生成行程。', zhHant: '找不到符合出行條件的地點，因此無法產生行程。' },
  // 🔴 「없다」를 그대로 옮긴다 — 「아직 준비 중」처럼 돌려 말하면 못 지키는 약속이
  //    그대로 남는다 (S15P21E201-1044).
  '지금은 이 조건을 확인할 장소 자료가 없어요 — 골라도 지금은 가려낼 수 없어요.': { ja: '今はこの条件を確認できる場所データがありません — 選んでも今は絞り込めません。', zhHans: '目前没有可用于核对该条件的地点数据 — 即使选择，现在也无法筛选。', zhHant: '目前沒有可用於核對該條件的地點資料 — 即使選擇，現在也無法篩選。' },
  '휠체어·유아차·큰 짐은 여행마다 달라서 여행 조건 화면에서 물어봐요.': { ja: '車いす・ベビーカー・大きな荷物は旅行ごとに異なるため、旅行条件の画面でお尋ねします。', zhHans: '轮椅、婴儿车和大件行李每次旅行都不同，会在旅行条件页面询问。', zhHant: '輪椅、嬰兒車和大件行李每次旅行都不同，會在旅行條件頁面詢問。' },
  '서버에 저장하지 못했어요. 이 기기에는 적어 뒀어요 — 한 번 더 눌러 보시고, 그래도 안 되면 그대로 진행해도 괜찮아요.': { ja: 'サーバーに保存できませんでした。この端末には記録してあります — もう一度お試しいただき、それでもだめならそのまま進めても大丈夫です。', zhHans: '未能保存到服务器。已记录在本设备上 — 请再试一次，如果仍然不行，继续进行也没问题。', zhHant: '未能儲存到伺服器。已記錄在本裝置上 — 請再試一次，如果仍然不行，繼續進行也沒問題。' },
  '이번엔 건너뛰기': { ja: '今回はスキップ', zhHans: '这次先跳过', zhHant: '這次先跳過' },
