  '이 코스 저장해 두기': { ja: 'このコースを保存しておく', zhHans: '收藏这条路线', zhHant: '收藏這條路線' },
  '이 코스로 일정 만들기 →': { ja: 'このコースで日程を作る →', zhHans: '用这条路线生成行程 →', zhHant: '用這條路線生成行程 →' },
  '이 코스 선택': { ja: 'このコースを選ぶ', zhHans: '选择这条路线', zhHant: '選擇這條路線' },
  '장소 이름을 입력해 보세요 — 예: 광안리, 감천문화마을': { ja: '場所の名前を入力してみてください — 例: Gwangalli, Gamcheon', zhHans: '试着输入地点名称 — 例: Gwangalli, Gamcheon', zhHant: '試著輸入地點名稱 — 例: Gwangalli, Gamcheon' },
  '검색어 지우기': { ja: '検索語を消す', zhHans: '清除搜索词', zhHant: '清除搜尋字詞' },
  '찾는 중이에요…': { ja: '検索しています…', zhHans: '正在搜索…', zhHant: '正在搜尋…' },
  '장소를 찾지 못했어요. 잠시 후 다시 시도해 주세요.': { ja: '場所を検索できませんでした。しばらくしてからもう一度お試しください。', zhHans: '暂时无法搜索地点，请稍后再试。', zhHant: '暫時無法搜尋地點，請稍後再試。' },
  '그런 이름의 장소가 없어요.': { ja: 'その名前の場所はありません。', zhHans: '没有这个名称的地点。', zhHant: '沒有這個名稱的地點。' },
  '✓ 담김': { ja: '✓ 追加済み', zhHans: '✓ 已加入', zhHant: '✓ 已加入' },
  '출발을 누르면 위치 추적이 시작돼요': { ja: '「出発」を押すと位置の記録が始まります', zhHans: '点击「出发」后开始记录位置', zhHant: '點擊「出發」後開始記錄位置' },
  '도착은 GPS로 자동 기록돼요': { ja: '到着は GPS で自動的に記録されます', zhHans: '到达会通过 GPS 自动记录', zhHant: '抵達會透過 GPS 自動記錄' },
  'GPS 신호가 약해요 · 직접 찍어 주세요': { ja: 'GPS の電波が弱いです · 手動で記録してください', zhHans: 'GPS 信号较弱 · 请手动记录', zhHant: 'GPS 訊號較弱 · 請手動記錄' },
  '지금 · 위치 추적 중': { ja: '現在 · 位置を記録中', zhHans: '当前 · 正在记录位置', zhHant: '目前 · 正在記錄位置' },
  '지금': { ja: '現在', zhHans: '当前', zhHant: '目前' },
  '⏸ 일정 중지': { ja: '⏸ 日程を一時停止', zhHans: '⏸ 暂停行程', zhHant: '⏸ 暫停行程' },
  '▶ 출발': { ja: '▶ 出発', zhHans: '▶ 出发', zhHant: '▶ 出發' },
  '이번 부산 여행,\n어떻게 다닐까요?': { ja: '今回の釜山旅行、\nどう回りましょうか?', zhHans: '这次釜山之旅，\n打算怎么玩?', zhHant: '這次釜山之旅，\n打算怎麼玩?' },
  '홈에서 받은 출발지·날짜·인원은 그대로 써요. 여기서는 취향과 조건만 열 가지 물어보고, 답한 만큼 일정이 정확해져요.': { ja: 'ホームで受け取った出発地・日付・人数はそのまま使います。ここでは好みと条件を10個だけお尋ねし、答えた分だけ日程が正確になります。', zhHans: '首页填写的出发地、日期和人数会直接沿用。这里只问 10 个关于喜好和条件的问题，回答越多行程越准确。', zhHant: '首頁填寫的出發地、日期和人數會直接沿用。這裡只問 10 個關於喜好和條件的問題，回答越多行程越準確。' },
  '홈에서 받은 정보': { ja: 'ホームで受け取った情報', zhHans: '来自首页的信息', zhHant: '來自首頁的資訊' },
  '계정에 기억된 취향': { ja: 'アカウントに記憶された好み', zhHans: '账户中记住的偏好', zhHant: '帳戶中記住的偏好' },
  '마이페이지 › 여행 취향': { ja: 'マイページ › 旅行の好み', zhHans: '我的主页 › 旅行偏好', zhHant: '我的主頁 › 旅行偏好' },
  '이미 아는 건 다시 묻지 않고 기본값으로 채워요. 이번 여행에만 다르게 하고 싶으면 질문에서 바꾸면 돼요.': { ja: 'すでに分かっていることは再度お尋ねせず、既定値で埋めます。今回の旅行だけ変えたい場合は質問で変更できます。', zhHans: '已知的内容不会再问，会用默认值填入。若只想这次旅行有所不同，在问题里修改即可。', zhHant: '已知的內容不會再問，會用預設值填入。若只想這次旅行有所不同，在問題裡修改即可。' },
  '이렇게 반영돼요': { ja: 'このように反映されます', zhHans: '会这样体现', zhHant: '會這樣體現' },
  '여행표 상세 보기': { ja: '旅行カードの詳細を見る', zhHans: '查看旅行卡详情', zhHant: '查看旅行卡詳情' },
  '출발 시각': { ja: '出発時刻', zhHans: '出发时间', zhHant: '出發時間' },
  '도착': { ja: '到着', zhHans: '到达', zhHant: '抵達' },
  '눌러서 여행표 상세 보기 ↻': { ja: 'タップして旅行カードの詳細を見る ↻', zhHans: '点击查看旅行卡详情 ↻', zhHant: '點擊查看旅行卡詳情 ↻' },
  '앞면으로 돌리기': { ja: '表に戻す', zhHans: '翻回正面', zhHant: '翻回正面' },
  '진행 상태': { ja: '進行状況', zhHans: '进度', zhHant: '進度' },
  '생성 완료': { ja: '作成完了', zhHans: '生成完成', zhHant: '生成完成' },
