  '서핑 · 한적한 해변': { ja: 'サーフィン · 静かなビーチ', zhHans: '冲浪 · 安静的海滩', zhHant: '衝浪 · 安靜的海灘' },
  '해수욕장 · 해안 산책로': { ja: '海水浴場 · 海岸の散歩道', zhHans: '海水浴场 · 海岸步道', zhHant: '海水浴場 · 海岸步道' },
