  '시장 · 번화가 · 축제': { ja: '市場 · 繁華街 · 祭り', zhHans: '市场 · 商业区 · 庆典', zhHant: '市場 · 商業區 · 慶典' },
  '해변 · 공원 · 산책': { ja: 'ビーチ · 公園 · 散歩', zhHans: '海滩 · 公园 · 散步', zhHant: '海灘 · 公園 · 散步' },
  '골목 · 마을 · 서점': { ja: '路地 · 村 · 書店', zhHans: '小巷 · 村落 · 书店', zhHant: '小巷 · 村落 · 書店' },
  '야경 · 노을 · 다리': { ja: '夜景 · 夕焼け · 橋', zhHans: '夜景 · 晚霞 · 大桥', zhHant: '夜景 · 晚霞 · 大橋' },
  '3시간에 한 곳 꼴 · 머무는 시간 길게': { ja: '3時間に1か所ほど · 滞在は長めに', zhHans: '约每 3 小时一处 · 停留时间更长', zhHant: '約每 3 小時一處 · 停留時間更長' },
  '2시간에 한 곳 꼴': { ja: '2時間に1か所ほど', zhHans: '约每 2 小时一处', zhHant: '約每 2 小時一處' },
  '1시간 반에 한 곳 꼴 · 이동 빠르게': { ja: '1時間半に1か所ほど · 移動は速く', zhHans: '约每 1.5 小时一处 · 快速移动', zhHant: '約每 1.5 小時一處 · 快速移動' },
  '지하철·버스 환승 최소': { ja: '地下鉄・バスの乗り換え最小', zhHans: '地铁/公交换乘最少', zhHant: '地鐵/公車轉乘最少' },
  '주차 가능한 곳 우선': { ja: '駐車できる場所を優先', zhHans: '优先可停车的地点', zhHant: '優先可停車的地點' },
  '한 동네 안에서 촘촘히': { ja: '一つの街の中を密に', zhHans: '在同一片区域内紧凑安排', zhHant: '在同一片區域內緊湊安排' },
  '서면 · 범일동': { ja: '西面 · 凡一洞', zhHans: '西面 · 凡一洞', zhHant: '西面 · 凡一洞' },
  '여름 점심': { ja: '夏のランチ', zhHans: '夏日午餐', zhHant: '夏日午餐' },
  '자갈치 · 기장': { ja: 'チャガルチ · 機張', zhHans: '札嘎其 · 机张', zhHant: '札嘎其 · 機張' },
  '부평깡통시장': { ja: '富平カントン市場', zhHans: '富平罐头市场', zhHant: '富平罐頭市場' },
  '남포동 간식': { ja: '南浦洞のおやつ', zhHans: '南浦洞小吃', zhHant: '南浦洞小吃' },
  '전포 · 해리단길': { ja: '田浦 · ヘリダン通り', zhHans: '田浦 · 海里团路', zhHant: '田浦 · 海里團路' },
  '%d개 지역 안에서만 장소를 골라요. 지역 사이 이동은 하루에 한 번 이하로 묶어요.': { ja: '%dつのエリア内でだけ場所を選びます。エリア間の移動は1日1回以下にまとめます。', zhHans: '只在这 %d 个区域内选择地点，区域之间每天最多移动一次。', zhHant: '只在這 %d 個區域內選擇地點，區域之間每天最多移動一次。' },
  '지역을 고르면 그 안에서만 장소를 골라요.': { ja: 'エリアを選ぶと、その中だけで場所を選びます。', zhHans: '选好区域后，只在其中选择地点。', zhHant: '選好區域後，只在其中選擇地點。' },
  '고른 갈래가 하루 정차지의 약 70%를 차지해요. 나머지는 이동 동선에 맞춰 채워요.': { ja: '選んだ種類が1日の立ち寄り先の約70%を占めます。残りは動線に合わせて埋めます。', zhHans: '你选的类别约占每天停留点的 70%，其余按路线补齐。', zhHant: '你選的類別約佔每天停留點的 70%，其餘按路線補齊。' },
  '최대 셋. 고른 갈래가 정차지의 대부분을 차지해요.': { ja: '最大3つ。選んだ種類が立ち寄り先の大半を占めます。', zhHans: '最多三项。你选的类别会占停留点的大部分。', zhHant: '最多三項。你選的類別會佔停留點的大部分。' },
  '3시간에 한 곳 꼴이에요. 12시간 하루면 4곳, 한 곳에 오래 머물러요.': { ja: '3時間に1か所ほどです。12時間の1日なら4か所、1か所に長く滞在します。', zhHans: '约每 3 小时一处。12 小时的一天去 4 处，每处停留较久。', zhHant: '約每 3 小時一處。12 小時的一天去 4 處，每處停留較久。' },
  '2시간에 한 곳 꼴이에요. 12시간 하루면 6곳이에요.': { ja: '2時間に1か所ほどです。12時間の1日なら6か所です。', zhHans: '约每 2 小时一处。12 小时的一天去 6 处。', zhHant: '約每 2 小時一處。12 小時的一天去 6 處。' },
  '1시간 반에 한 곳 꼴이에요. 12시간 하루면 8곳, 이동은 가까운 순으로 붙여요.': { ja: '1時間半に1か所ほどです。12時間の1日なら8か所、移動は近い順につなぎます。', zhHans: '约每 1.5 小时一处。12 小时的一天去 8 处，按由近到远的顺序串联。', zhHant: '約每 1.5 小時一處。12 小時的一天去 8 處，按由近到遠的順序串聯。' },
  '하루에 도는 장소 수와 머무는 시간이 정해져요.': { ja: '1日に回る場所の数と滞在時間が決まります。', zhHans: '这决定每天去几个地点、每处停留多久。', zhHant: '這決定每天去幾個地點、每處停留多久。' },
  '고른 분위기의 장소를 저녁·마무리 시간대에 우선 배치해요.': { ja: '選んだ雰囲気の場所を夕方・締めの時間帯に優先して配置します。', zhHans: '你选的氛围的地点会优先安排在傍晚和收尾时段。', zhHant: '你選的氛圍的地點會優先安排在傍晚和收尾時段。' },
  '분위기는 시간대 배치(아침/저녁)에 반영돼요.': { ja: '雰囲気は時間帯の配置（朝/夕）に反映されます。', zhHans: '氛围会影响地点安排在哪个时段（早/晚）。', zhHant: '氛圍會影響地點安排在哪個時段（早/晚）。' },
  '점심·저녁 자리는 고른 음식이 있는 곳 근처로 잡아요.': { ja: '昼食・夕食の場所は選んだ料理がある所の近くにします。', zhHans: '午餐和晚餐会安排在你选的美食附近。', zhHant: '午餐和晚餐會安排在你選的美食附近。' },
  '식사 시간대의 장소 선택에 반영돼요.': { ja: '食事の時間帯の場所選びに反映されます。', zhHans: '这会影响用餐时段的地点选择。', zhHant: '這會影響用餐時段的地點選擇。' },
