  // ── 순수 모듈이 던지는 실패 문장 — 화면이 localizeMessage 로 그린다 (src/i18n/messages.ts, S15P21E201-1361) ──
  '서버 응답이 늦어 요청을 마쳤어요. 잠시 후 다시 시도해 주세요.': { ja: 'サーバーの応答が遅く、リクエストを打ち切りました。しばらくしてからもう一度お試しください。', zhHans: '服务器响应过慢，请求已结束。请稍后再试。', zhHant: '伺服器回應過慢，請求已結束。請稍後再試。' },
  '서버에 연결할 수 없어요. 잠시 후 다시 시도해 주세요.': { ja: 'サーバーに接続できません。しばらくしてからもう一度お試しください。', zhHans: '无法连接服务器。请稍后再试。', zhHant: '無法連線伺服器。請稍後再試。' },
  '서버가 잠시 응답하지 못했어요. 잠시 후 다시 시도해 주세요. (HTTP %d)': { ja: 'サーバーが一時的に応答できませんでした。しばらくしてからもう一度お試しください。(HTTP %d)', zhHans: '服务器暂时无法响应。请稍后再试。(HTTP %d)', zhHant: '伺服器暫時無法回應。請稍後再試。(HTTP %d)' },
  '요청을 취소했어요.': { ja: 'リクエストを取り消しました。', zhHans: '已取消请求。', zhHant: '已取消請求。' },
  '요청이 취소됐어요.': { ja: 'リクエストが取り消されました。', zhHans: '请求已取消。', zhHant: '請求已取消。' },
  '요청을 처리하지 못했어요.': { ja: 'リクエストを処理できませんでした。', zhHans: '无法处理请求。', zhHant: '無法處理請求。' },
  '사진 파일 읽기가 중단됐어요': { ja: '写真ファイルの読み込みが中断されました', zhHans: '读取照片文件被中断', zhHant: '讀取照片檔案被中斷' },
  // 결과만으로는 «사용자가 취소»와 «못 돌아와서 닫음»을 못 가른다 — 둘 다에 참인 말(S15P21E201-1480, oauth.ts)
  '로그인을 마치지 못했어요. 창을 닫았거나 연결이 끊겼을 수 있으니 다시 시도해 주세요.': { ja: 'ログインを完了できませんでした。画面を閉じたか、接続が切れた可能性があります。もう一度お試しください。', zhHans: '未能完成登录。可能是关闭了窗口或网络连接中断，请重试。', zhHant: '未能完成登入。可能是關閉了視窗或網路連線中斷，請重試。' },
  '소셜 로그인을 완료하지 못했어요.': { ja: 'ソーシャルログインを完了できませんでした。', zhHans: '无法完成社交账号登录。', zhHant: '無法完成社群帳號登入。' },
  '일정의 장소 위치를 한 곳도 받지 못했어요.': { ja: '日程の場所の位置情報が一つも取得できませんでした。', zhHans: '行程中没有任何地点带有位置信息。', zhHant: '行程中沒有任何地點帶有位置資訊。' },
  '다른 변경이 먼저 반영됐어요. 최신 일정을 불러와 다시 시도해 주세요.': { ja: '別の変更が先に反映されました。最新の日程を読み込んでからもう一度お試しください。', zhHans: '另一项更改已先行生效。请加载最新行程后再试。', zhHant: '另一項變更已先行生效。請載入最新行程後再試。' },
  '순서 목록이 이 날짜의 장소와 맞지 않아요. 새로고침 후 다시 시도해 주세요.': { ja: '並び順のリストがこの日の場所と一致しません。更新してからもう一度お試しください。', zhHans: '顺序列表与当天的地点不匹配。请刷新后再试。', zhHant: '順序清單與當天的地點不符。請重新整理後再試。' },
  '고정된 장소는 자리를 옮길 수 없어요. 고정을 먼저 풀어 주세요.': { ja: '固定した場所は移動できません。先に固定を解除してください。', zhHans: '已锁定的地点无法移动。请先解锁。', zhHant: '已鎖定的地點無法移動。請先解鎖。' },
  '되돌릴 변경 사항이 없어요.': { ja: '元に戻す変更がありません。', zhHans: '没有可撤销的更改。', zhHant: '沒有可復原的變更。' },
  '남은 일정이 하루 안에 다 들어가지 않아요. 넘치는 방문지를 먼저 확인해 주세요.': { ja: '残りの予定が1日に収まりません。あふれた訪問地を先に確認してください。', zhHans: '剩余行程无法在一天内完成。请先查看超出的地点。', zhHant: '剩餘行程無法在一天內完成。請先查看超出的地點。' },
  '지금은 일정을 만들 수 없어요. 잠시 뒤 다시 시도해 주세요. 입력한 조건은 그대로 남아 있어요.': { ja: '今は日程を作成できません。しばらくしてからもう一度お試しください。入力した条件はそのまま残っています。', zhHans: '暂时无法生成行程。请稍后再试。你输入的条件会保留。', zhHant: '暫時無法生成行程。請稍後再試。你輸入的條件會保留。' },
  '공유 일정을 불러오지 못했어요. 잠시 후 다시 시도해 주세요.': { ja: '共有された日程を読み込めませんでした。しばらくしてからもう一度お試しください。', zhHans: '无法加载共享行程。请稍后再试。', zhHant: '無法載入共享行程。請稍後再試。' },
  '동영상이 너무 커요. 더 짧은 영상으로 올려주세요.': { ja: '動画が大きすぎます。もっと短い動画をアップロードしてください。', zhHans: '视频太大了。请上传更短的视频。', zhHant: '影片太大了。請上傳更短的影片。' },
  'mp4 동영상만 올릴 수 있어요.': { ja: 'mp4 の動画のみアップロードできます。', zhHans: '只能上传 mp4 视频。', zhHant: '只能上傳 mp4 影片。' },
