  '사진에서 읽은 것이 아니라 AI 가 덧붙인 설명이에요': { ja: '写真から読み取った内容ではなく、AIが補足した説明です', zhHans: '这不是从照片中读取的内容,而是 AI 补充的说明', zhHant: '這不是從照片中讀取的內容,而是 AI 補充的說明' },
  '이 음식은 아직 설명해 드릴 수 없어요.': { ja: 'この料理はまだご説明できません。', zhHans: '暂时无法为您介绍这道菜。', zhHant: '暫時無法為您介紹這道菜。' },
  '그림을 그리고 있어요 (10초쯤 걸려요)': { ja: '絵を描いています(10秒ほどかかります)', zhHans: '正在绘制图片(约需 10 秒)', zhHant: '正在繪製圖片(約需 10 秒)' },
  'AI 가 그린 그림이에요 — 실제 나오는 음식과 달라요': { ja: 'AIが描いた絵です — 実際に出てくる料理とは異なります', zhHans: '这是 AI 绘制的图片 — 与实际上菜的样子不同', zhHant: '這是 AI 繪製的圖片 — 與實際上菜的樣子不同' },
  '이 음식 설명을 가져오지 못했어요.': { ja: 'この料理の説明を取得できませんでした。', zhHans: '未能获取这道菜的说明。', zhHant: '未能取得這道菜的說明。' },
  '그림은 조금 뒤에 다시 만들 수 있어요. 설명은 그대로 보실 수 있어요.': { ja: '絵は少し後にまた作れます。説明はそのままご覧いただけます。', zhHans: '稍后可以再次生成图片。说明仍可正常查看。', zhHant: '稍後可以再次生成圖片。說明仍可正常查看。' },
  '사진에 적힌 글자를 읽고, 지금 쓰는 언어로 옮겨 드려요.': { ja: '写真に書かれた文字を読み取り、今お使いの言語に翻訳します。', zhHans: '读取照片上的文字,并翻译成您当前使用的语言。', zhHant: '讀取照片上的文字,並翻譯成您目前使用的語言。' },
  '가볼래 · 부산': { ja: 'GABOLLE · 釜山', zhHans: 'GABOLLE · 釜山', zhHant: 'GABOLLE · 釜山' },
  '누구나 안심하고\n부산을 여행하도록': { ja: '誰もが安心して\n釜山を旅できるように', zhHans: '让每个人都能放心地\n畅游釜山', zhHant: '讓每個人都能放心地\n暢遊釜山' },
  '연령 확인은 안전한 서비스 이용을 위한 최소한의 절차예요. 생년월일은 수집하지 않습니다.': { ja: '年齢確認は安全なサービス利用のための最小限の手続きです。生年月日は収集しません。', zhHans: '年龄确认是为了安全使用服务而进行的最基本步骤。我们不会收集您的出生日期。', zhHant: '年齡確認是為了安全使用服務而進行的最基本步驟。我們不會收集您的出生日期。' },
  '✓ 생년월일 미수집': { ja: '✓ 生年月日は収集しません', zhHans: '✓ 不收集出生日期', zhHant: '✓ 不收集出生日期' },
  '✓ 한 번만 확인': { ja: '✓ 確認は一度だけ', zhHans: '✓ 仅需确认一次', zhHant: '✓ 僅需確認一次' },
