  '비회원으로 먼저 둘러보기': { ja: 'まずはゲストとして利用する', zhHans: '先以访客身份浏览', zhHant: '先以訪客身份瀏覽' },
  '저장한 답변을 확인하지 못했어요. 이미 답한 설문을 다시 묻지 않도록 연결을 확인한 뒤 재시도해 주세요.': { ja: '保存した回答を確認できませんでした。すでに回答した内容を再度尋ねないよう、接続を確認してから再試行してください。', zhHans: '无法确认已保存的回答。请检查网络连接后重试,以免重复询问已回答的问卷。', zhHant: '無法確認已保存的回答。請檢查網路連線後重試,以免重複詢問已回答的問卷。' },
