  '큰 짐': { ja: '大きな荷物', zhHans: '大件行李', zhHant: '大件行李' },
  '안전 조건 확인 완료': { ja: '安全条件確認完了', zhHans: '确认安全条件', zhHant: '確認安全條件' },
  '이동 환경 확인 완료': { ja: '移動環境確認完了', zhHans: '确认出行环境', zhHant: '確認出行環境' },
  '알레르기와 이동 지원 정보는 이 여행을 준비하는 동안에만 사용하며, 기기에 저장하지 않습니다.': { ja: 'アレルギーと移動支援情報は、この旅行を準備する間だけ使用し、端末には保存しません。', zhHans: '过敏和行动支援信息仅在准备本次旅行期间使用,不会保存在设备上。', zhHant: '過敏和行動支援資訊僅在準備本次旅行期間使用,不會保存在裝置上。' },
  '알레르기와 식단의 ‘해당 없음’ 또는 적용 조건을 선택해 주세요.': { ja: 'アレルギーと食事について「該当なし」または該当する条件を選択してください。', zhHans: '请为过敏和饮食选择"无"或适用的条件。', zhHant: '請為過敏和飲食選擇「無」或適用的條件。' },
  '최종 확인 단계로 이동합니다.': { ja: '最終確認ステップに進みます。', zhHans: '前往最终确认步骤。', zhHant: '前往最終確認步驟。' },
  '누르면 아직 답하지 않은 필수 조건을 안내합니다.': { ja: '押すとまだ答えていない必須条件を案内します。', zhHans: '点击可查看尚未回答的必要条件。', zhHant: '點擊可查看尚未回答的必要條件。' },
  '최종 확인으로': { ja: '最終確認へ', zhHans: '前往最终确认', zhHant: '前往最終確認' },
