  '일정을 만들지 못했어요': { ja: '日程を作成できませんでした', zhHans: '未能生成行程', zhHant: '未能生成行程' },
  'AI가 당신만을 위한\n부산 여행을 만들고 있어요': { ja: 'AIがあなただけのために\n釜山旅行を作成しています', zhHans: 'AI 正在为您\n打造专属釜山之旅', zhHant: 'AI 正在為您\n打造專屬釜山之旅' },
  '부산 동선을 조금 더 다듬고 있어요. 화면을 닫아도 작업은 계속됩니다.': { ja: '釜山の移動ルートをもう少し調整しています。画面を閉じても作業は続きます。', zhHans: '正在进一步优化釜山的路线。即使关闭页面,处理也会继续进行。', zhHant: '正在進一步優化釜山的路線。即使關閉頁面,處理也會繼續進行。' },
