  '이 여행을 삭제할까요?': { ja: 'この旅行を削除しますか?', zhHans: '要删除此次旅行吗?', zhHant: '要刪除此次旅行嗎?' },
  '이 여행에서 나갈까요?': { ja: 'この旅行から退出しますか?', zhHans: '要退出此次旅行吗?', zhHant: '要退出此次旅行嗎?' },
