  '아직 바뀐 내용이 없어요.': { ja: 'まだ変更内容がありません。', zhHans: '尚无变更内容。', zhHant: '尚無變更內容。' },
  '동행자 초대하기': { ja: '同行者を招待', zhHans: '邀请同伴', zhHant: '邀請同伴' },
  '부산에서 보낸 2일 — 바다와 골목을 따라, 부산': { ja: '釜山で過ごした2日間 — 海と路地を辿って、釜山', zhHans: '在釜山度过的2天 — 沿着海岸与小巷,釜山', zhHant: '在釜山度過的2天 — 沿著海岸與小巷,釜山' },
  '여행 후 · 자동 회고': { ja: '旅行後 ・自動振り返り', zhHans: '旅行结束后 · 自动回顾', zhHant: '旅行結束後 · 自動回顧' },
  '아래 숫자와 시간표는 화면을 보여주기 위한 예시예요. 실제 여행 기록이 아니에요.': { ja: '下記の数字と時間表は画面表示のための例です。実際の旅行記録ではありません。', zhHans: '下方数字和时间表仅为展示画面的示例,并非实际旅行记录。', zhHant: '下方數字和時間表僅為展示畫面的範例,並非實際旅行記錄。' },
  '부산에서 보낸 2일': { ja: '釜山で過ごした2日間', zhHans: '在釜山度过的2天', zhHant: '在釜山度過的2天' },
  '바다와 골목을 따라, 부산': { ja: '海と路地を辿って、釜山', zhHans: '沿着海岸与小巷,釜山', zhHant: '沿著海岸與小巷,釜山' },
