  '앱 기능을 실행하는 부산 여행 도우미': { ja: 'アプリ機能を実行する釜山旅行アシスタント', zhHans: '为您执行应用功能的釜山旅行助手', zhHant: '為您執行應用程式功能的釜山旅行助手' },
