  '여행 중 필요한 기능을 바로 실행하세요': { ja: '旅行中に必要な機能をすぐに実行しましょう', zhHans: '立即运行旅行中所需的功能', zhHant: '立即執行旅行中所需的功能' },
  '현장 문장은 크게 보거나 음성으로 듣고, 메뉴판 번역 도구도 바로 열 수 있어요.': { ja: '現地で使う文章を大きく表示したり音声で聞いたりでき、メニュー翻訳ツールもすぐに開けます。', zhHans: '可以放大查看或语音收听现场用语,也能立即打开菜单翻译工具。', zhHant: '可以放大查看或語音收聽現場用語,也能立即打開菜單翻譯工具。' },
  '안녕하세요! 부산 일정과 여행 중 필요한 말을 앱 기능으로 바로 도와드릴게요.': { ja: 'こんにちは!釜山の日程や旅行中に必要な言葉を、アプリ機能ですぐにお手伝いします。', zhHans: '您好!我可以通过应用功能立即帮您处理釜山行程和旅行中需要的用语。', zhHant: '您好!我可以透過應用程式功能立即幫您處理釜山行程和旅行中需要的用語。' },
  '이렇게 검색해 보세요': { ja: 'このように検索してみてください', zhHans: '试试这样搜索', zhHant: '試試這樣搜尋' },
  '찾은 여행 조건': { ja: '見つかった旅行条件', zhHans: '找到的旅行条件', zhHant: '找到的旅行條件' },
  '일정 초안에 적용됨 ✓': { ja: '日程案に適用済み ✓', zhHans: '已应用到行程草案 ✓', zhHant: '已套用到行程草案 ✓' },
  '일정에 적용하고 확인하기': { ja: '日程に適用して確認する', zhHans: '应用到行程并确认', zhHant: '套用到行程並確認' },
  '크게 보고 듣기': { ja: '大きく表示・聞く', zhHans: '放大查看并收听', zhHant: '放大檢視並收聽' },
  '답변 준비 중': { ja: '回答準備中', zhHans: '正在准备回复', zhHant: '正在準備回覆' },
  '생각하는 중…': { ja: '考え中…', zhHans: '思考中…', zhHant: '思考中…' },
  '기능이나 궁금한 점 검색': { ja: '機能や気になることを検索', zhHans: '搜索功能或提出问题', zhHant: '搜尋功能或提出問題' },
