  '입력 지우기': { ja: '入力を消去', zhHans: '清除输入', zhHant: '清除輸入' },
  '검색': { ja: '検索', zhHans: '搜索', zhHant: '搜尋' },
  '안전 조건은 AI가 변경하지 않으며, 일정 적용 전 반드시 확인합니다.': { ja: '安全条件はAIが変更することはなく、日程に適用する前に必ず確認します。', zhHans: 'AI 绝不会更改您的安全条件,并且在应用到行程前一定会请您确认。', zhHant: 'AI 絕不會更改您的安全條件,並且在套用到行程前一定會請您確認。' },
