  // 피드 공유 — 여행 화면 「공유」 · 글쓰기 코스 링크 · 코스 카드(S15P21E201-1593).
  '공유': { ja: '共有', zhHans: '分享', zhHant: '分享' },
  '✓ 이 여행과 연결됨': { ja: '✓ この旅行と連携済み', zhHans: '✓ 已关联此行程', zhHant: '✓ 已連結此行程' },
  '코스 링크 함께 올리기': { ja: 'コースリンクも投稿する', zhHans: '一并发布路线链接', zhHant: '一併發佈路線連結' },
  '올릴 때 읽기 전용 링크를 만들어 본문 끝에 붙여요. 피드에는 코스 카드로 보여요. 30일 뒤 만료돼요.': { ja: '投稿時に閲覧専用リンクを作って本文の最後に付けます。フィードではコースカードとして表示されます。30日後に期限切れになります。', zhHans: '发布时会生成只读链接并附在正文末尾。在动态中以路线卡片显示，30天后失效。', zhHant: '發佈時會產生唯讀連結並附在內文末尾。在動態中以路線卡片顯示，30天後失效。' },
  '본문이 길어 코스 링크를 붙일 수 없어요. 조금 줄이거나 코스 링크를 꺼 주세요.': { ja: '本文が長すぎてコースリンクを付けられません。少し短くするか、コースリンクをオフにしてください。', zhHans: '正文太长，无法附上路线链接。请缩短一些或关闭路线链接。', zhHant: '內文太長，無法附上路線連結。請縮短一些或關閉路線連結。' },
  '코스 링크를 만들지 못했어요. 잠시 뒤 다시 올리거나 코스 링크를 끄고 올려 주세요.': { ja: 'コースリンクを作成できませんでした。しばらくしてから再度投稿するか、コースリンクをオフにして投稿してください。', zhHans: '无法生成路线链接。请稍后重新发布，或关闭路线链接后发布。', zhHant: '無法產生路線連結。請稍後重新發佈，或關閉路線連結後發佈。' },
  '코스': { ja: 'コース', zhHans: '路线', zhHant: '路線' },
