  '실패 · 다시 시도': { ja: '失敗 ・再試行', zhHans: '失败 · 重试', zhHant: '失敗 · 重試' },
  '+ 사진 추가': { ja: '+ 写真を追加', zhHans: '+ 添加照片', zhHant: '+ 新增照片' },
  '사진의 위치 정보는 자동으로 제거되고, 위치는 지역 단위로만 저장돼요. 장소를 연결하면 그 장소 소개에도 사진이 함께 보일 수 있고, 글을 지우면 거기서도 빠져요.': { ja: '写真の位置情報は自動的に削除され、位置は地域単位でのみ保存されます。場所を連携すると、その場所の紹介にも写真が一緒に表示されることがあり、投稿を削除するとそこからも消えます。', zhHans: '照片的位置信息会自动删除,仅保存大致地区。若关联地点,该地点介绍中也可能一并显示您的照片;删除帖子时该照片也会随之移除。', zhHant: '照片的位置資訊會自動刪除,僅保存大致地區。若關聯地點,該地點介紹中也可能一併顯示您的照片;刪除貼文時該照片也會隨之移除。' },
  '지역 (선택)': { ja: '地域(任意)', zhHans: '地区(可选)', zhHant: '地區(可選)' },
  '공개 시점': { ja: '公開時期', zhHans: '公开时间', zhHant: '公開時間' },
  '"여행이 끝난 뒤"를 고르면 여행이 끝난 다음 날부터 보여요.': { ja: '「旅行が終わった後」を選ぶと、旅行終了の翌日から表示されます。', zhHans: '选择"旅行结束后"将在旅行结束的第二天开始显示。', zhHant: '選擇「旅行結束後」將在旅行結束的隔天開始顯示。' },
  '기록 올리기': { ja: '記録を投稿', zhHans: '发布记录', zhHant: '發布記錄' },
  '축제 정보를 불러오지 못했어요.': { ja: '祭り情報を読み込めませんでした。', zhHans: '无法加载节庆信息。', zhHant: '無法載入節慶資訊。' },
  '부산 축제': { ja: '釜山の祭り', zhHans: '釜山节庆', zhHant: '釜山節慶' },
  '여행 날짜에 열리는 축제': { ja: '旅行日程中に開催される祭り', zhHans: '旅行期间举办的节庆', zhHant: '旅行期間舉辦的節慶' },
