  '날짜를 바꿔 다시 조회해 보세요. 기간과 무관한 축제는 대신 보여드리지 않아요.': { ja: '日付を変えて再度検索してみてください。期間と関係ない祭りは代わりに表示しません。', zhHans: '请尝试更改日期重新查询。我们不会显示不在此期间内的节庆。', zhHant: '請嘗試更改日期重新查詢。我們不會顯示不在此期間內的節慶。' },
  '입장료 정보 확인 필요': { ja: '入場料情報の確認が必要', zhHans: '门票信息待确认', zhHant: '門票資訊待確認' },
  '로그인하면 도착 시간을 보여드려요': { ja: 'ログインすると到着時刻を表示します', zhHans: '登录后即可查看到站时间', zhHant: '登入後即可查看到站時間' },
  '버스 도착 정보는 한도가 있는 외부 자료라 로그인한 분에게만 보여드려요.': { ja: 'バス到着情報は利用制限のある外部データのため、ログインした方にのみ表示します。', zhHans: '公交到站信息为限量外部数据,仅向已登录用户显示。', zhHant: '公車到站資訊為限量外部資料,僅向已登入用戶顯示。' },
  '버스 정보가 아직 서버에 없어요': { ja: 'バス情報がまだサーバーにありません', zhHans: '服务器上暂无公交信息', zhHant: '伺服器上暫無公車資訊' },
  '곧 열려요. 조금 뒤에 다시 들러 주세요.': { ja: 'まもなく公開します。少し経ってからまたお越しください。', zhHans: '即将上线,请稍后再来查看。', zhHant: '即將上線,請稍後再來查看。' },
  '지금은 도착 정보를 못 받았어요': { ja: '現在到着情報を取得できませんでした', zhHans: '目前无法获取到站信息', zhHant: '目前無法取得到站資訊' },
  '버스 정보 제공처가 잠시 응답하지 않아요. 잠시 후 다시 시도해 주세요.': { ja: 'バス情報の提供元が一時的に応答していません。しばらくしてから再度お試しください。', zhHans: '公交信息提供方暂时无响应,请稍后再试。', zhHant: '公車資訊提供方暫時無回應,請稍後再試。' },
  '도착 정보를 불러오지 못했어요': { ja: '到着情報を読み込めませんでした', zhHans: '无法加载到站信息', zhHant: '無法載入到站資訊' },
