  '환율 기능이 아직 서버에 없어요': { ja: '為替レート機能がまだサーバーにありません', zhHans: '服务器上暂无汇率功能', zhHant: '伺服器上暫無匯率功能' },
  '오늘 환율을 못 받았어요': { ja: '本日のレートを取得できませんでした', zhHans: '无法获取今日汇率', zhHant: '無法取得今日匯率' },
  '환율 제공처가 잠시 응답하지 않아요. 잠시 후 다시 시도해 주세요.': { ja: '為替レート提供元が一時的に応答していません。しばらくしてから再度お試しください。', zhHans: '汇率提供方暂时无响应,请稍后再试。', zhHant: '匯率提供方暫時無回應,請稍後再試。' },
  '환율을 불러오지 못했어요': { ja: '為替レートを読み込めませんでした', zhHans: '无法加载汇率', zhHant: '無法載入匯率' },
  '환율 계산': { ja: '為替計算', zhHans: '汇率换算', zhHant: '匯率換算' },
  '가격표를 보고 바로 내 돈으로 바꿔 보세요.': { ja: '値札を見てすぐに自国の通貨に換算してみましょう。', zhHans: '看到价格标签,立即换算成您的货币。', zhHant: '看到價格標籤,立即換算成您的貨幣。' },
  '오늘 환율을 확인하고 있어요…': { ja: '本日のレートを確認しています…', zhHans: '正在查询今日汇率…', zhHant: '正在查詢今日匯率…' },
