  '부산 일정 만들기, 한국어 현장 문장, 로컬 스팟 탐색, 내 여행 찾기를 도와드릴 수 있어요.': { ja: '釜山日程作成、韓国語現地会話、ローカルスポット探索、マイ旅行検索をお手伝いできます。', zhHans: '我可以帮您规划釜山行程、提供韩语现场用语、探索本地景点,或查找您的旅行。', zhHant: '我可以幫您規劃釜山行程、提供韓語現場用語、探索在地景點,或查詢您的旅行。' },
