  '홈의 로컬 탐색에서 장소 이름이나 관심 있는 갈래로 찾아보세요. 위치 권한 없이도 둘러볼 수 있어요.': { ja: 'ホームのローカル探索で場所名や興味のあるジャンルで探してみてください。位置情報権限なしでも見て回れます。', zhHans: '在首页的本地探索中,按地点名称或感兴趣的类别搜索。无需位置权限也可以浏览。', zhHant: '在首頁的在地探索中,按地點名稱或感興趣的類別搜尋。無需位置權限也可以瀏覽。' },
