  '이번 여행은 평소와 다르신가요?': { ja: '今回の旅行はいつもと違いますか?', zhHans: '这次旅行和平时不一样吗?', zhHant: '這次旅行和平時不一樣嗎?' },
  '이번 여행에만 적용돼요. 평소 답은 그대로 둡니다.': { ja: '今回の旅行にのみ適用されます。普段の回答はそのまま残ります。', zhHans: '仅适用于本次旅行,您平时的回答将保持不变。', zhHant: '僅適用於本次旅行,您平時的回答將保持不變。' },
