  '보통 어떤 여행을 좋아하시는지 알면 추천 순서가 달라져요. 마이페이지에서 언제든 바꿀 수 있어요.': { ja: '普段どんな旅行がお好きかが分かると、おすすめの順番が変わります。マイページでいつでも変更できます。', zhHans: '了解您平时喜欢的旅行方式后，推荐顺序会随之变化。可随时在“我的页面”修改。', zhHant: '了解您平時喜歡的旅行方式後，推薦順序會隨之變化。可隨時在「我的頁面」修改。' },
