  '승차권을 눌러 뒤집으면 「일정 보기」가 있어요.': { ja: '乗車券をタップして裏返すと「旅程を見る」があります。', zhHans: '点击车票翻面即可看到“查看行程”。', zhHant: '點擊車票翻面即可看到「查看行程」。' },
  '필수 질문은 다 답했어요 · 출발지만 고르면 만들 수 있어요': { ja: '必須の質問は全部答えました · 出発地を選べば作れます', zhHans: '必填问题已全部回答 · 选好出发地即可生成', zhHant: '必填問題已全部回答 · 選好出發地即可生成' },
