  '서버에 닿지 못했어요. 잠시 후 다시 시도해 주세요.': { ja: 'サーバーに接続できませんでした。しばらくしてからもう一度お試しください。', zhHans: '无法连接服务器。请稍后再试。', zhHant: '無法連線伺服器。請稍後再試。' },
  '4. 사투리 목소리': { ja: '4. 方言の音声', zhHans: '4. 方言语音', zhHant: '4. 方言語音' },
  '「부산 사투리 한마디」의 목소리는 타입캐스트(Typecast, typecast.ai)의 AI 음성 「개나리」·「용식이」로 만들었습니다. 사람 목소리를 흉내 낸 합성음이며, 문장은 미리 만들어 앱에 넣어 두었습니다.': { ja: '「釜山方言ひとこと」の音声は Typecast(typecast.ai) の AI 音声「ケナリ」「ヨンシク」で作成しました。人の声を模した合成音声で、文章はあらかじめ生成してアプリに同梱しています。', zhHans: '“釜山方言一句话”的语音由 Typecast(typecast.ai) 的 AI 声音“开拿里”“龙植”生成。它是模仿人声的合成语音，句子已预先生成并内置于应用中。', zhHant: '「釜山方言一句話」的語音由 Typecast(typecast.ai) 的 AI 聲音「開拿里」「龍植」生成。它是模仿人聲的合成語音，句子已預先生成並內建於應用程式中。' },
  '5. 이용 조건': { ja: '5. 利用条件', zhHans: '5. 使用条款', zhHant: '5. 使用條款' },
  '내가 꼭 가고 싶다고 적은 곳': { ja: '必ず行きたいと書いた場所', zhHans: '您标记为必去的地方', zhHant: '您標記為必去的地方' },
  '관광지 자리를 다 채우지 못했어요. 대신 식당으로 메우지는 않았어요.': { ja: '観光地の枠を全部埋められませんでした。代わりに飲食店で埋めることはしていません。', zhHans: '没能填满所有景点位置，但也没有用餐厅来凑数。', zhHant: '沒能填滿所有景點位置，但也沒有用餐廳來湊數。' },
  '이 식단을 지원하는지 아직 확인되지 않은 곳이에요. 안 된다는 뜻은 아니에요.': { ja: 'この食事制限に対応しているかはまだ確認できていません。対応していないという意味ではありません。', zhHans: '尚未确认这家店是否支持您的饮食要求，这并不表示不支持。', zhHant: '尚未確認這家店是否支援您的飲食需求，這並不表示不支援。' },
  '휠체어·유아차·큰 짐으로 다니기 편한지 아직 확인되지 않은 곳이에요.': { ja: '車いす・ベビーカー・大きな荷物で移動しやすいか、まだ確認されていない場所です。', zhHans: '尚未确认此处是否便于轮椅、婴儿车或大件行李通行。', zhHant: '尚未確認此處是否便於輪椅、嬰兒車或大件行李通行。' },
  '주변 길이 가팔라요(추정). 휠체어·유아차·큰 짐으로는 힘들 수 있어요.': { ja: '周辺の道が急です(推定)。車いす・ベビーカー・大きな荷物では大変かもしれません。', zhHans: '周边道路较陡(推测)。使用轮椅、婴儿车或携带大件行李时可能会比较吃力。', zhHant: '周邊道路較陡(推測)。使用輪椅、嬰兒車或攜帶大件行李時可能會比較吃力。' },
  '휠체어·유아차로는 들어가기 어렵다고 확인된 곳이에요.': { ja: '車いすやベビーカーでは入りにくいと確認された場所です。', zhHans: '已确认此处轮椅或婴儿车难以进入。', zhHant: '已確認此處輪椅或嬰兒車難以進入。' },
  '알레르기 재료가 들었는지 아직 확인되지 않은 곳이에요. 드시기 전에 꼭 가게에 물어보세요.': { ja: 'アレルギー食材が含まれているか、まだ確認されていない場所です。食べる前に必ずお店に確認してください。', zhHans: '尚未确认此处是否含有您的过敏原食材。用餐前请务必向店家确认。', zhHant: '尚未確認此處是否含有您的過敏原食材。用餐前請務必向店家確認。' },
  '출발지에서 걸어갈 수 있어요': { ja: '出発地から歩いて行けます', zhHans: '从出发地步行可到', zhHant: '從出發地步行可到' },
  '이곳엔 계단이 있어요. 계단을 피하고 싶다고 하셨죠.': { ja: 'ここには階段があります。階段を避けたいとのことでしたね。', zhHans: '这里有台阶，而您说过想避开台阶。', zhHant: '這裡有台階，而您說過想避開台階。' },
  '정하신 걷는 거리보다 멀어요.': { ja: '設定した歩く距離より遠いです。', zhHans: '比您设定的步行距离更远。', zhHant: '比您設定的步行距離更遠。' },
  '조건에 맞는지 확인하지 못했어요. 안 맞는다는 뜻은 아니에요.': { ja: '条件に合うか確認できませんでした。合わないという意味ではありません。', zhHans: '未能确认是否符合条件，但这不代表不符合。', zhHant: '未能確認是否符合條件，但這不代表不符合。' },
  '확인이 안 돼서 뺐어요. 안 맞아서가 아니라 알 수 없어서예요.': { ja: '確認できなかったので外しました。合わないからではなく、分からないからです。', zhHans: '因为无法确认而排除了，并非因为不符合，而是无从得知。', zhHant: '因為無法確認而排除了，並非因為不符合，而是無從得知。' },
  '꼭 필요하다고 하신 조건인데 확인하지 못했어요.': { ja: '必須とされた条件ですが確認できませんでした。', zhHans: '这是您标记为必需的条件，但未能确认。', zhHant: '這是您標記為必需的條件，但未能確認。' },
  '선호하신다고 한 조건인데 확인하지 못했어요.': { ja: '希望とされた条件ですが確認できませんでした。', zhHans: '这是您偏好的条件，但未能确认。', zhHant: '這是您偏好的條件，但未能確認。' },
  '비교할 자료가 모자라 순서를 정하지 못했어요.': { ja: '比較する資料が足りず順位を決められませんでした。', zhHans: '可比较的资料不足，无法排序。', zhHant: '可比較的資料不足，無法排序。' },
  '그날 일정을 일부만 채웠어요. 넣을 곳이 모자랐어요.': { ja: 'その日の旅程は一部しか埋められませんでした。入れる場所が足りませんでした。', zhHans: '那天的行程只填了一部分，可加入的地点不够。', zhHant: '那天的行程只填了一部分，可加入的地點不夠。' },

